@inherits Umbraco.Cms.Web.Common.Views.UmbracoViewPage&lt;ContentModels.BlogFrontPage&gt;
@using ContentModels = Umbraco.Cms.Web.Common.PublishedModels;
@{
    Layout = null;
}
&lt;!DOCTYPE html&gt;
&lt;html&gt;
&lt;head&gt;
    &lt;title&gt;@Model.Value("title")&lt;/title&gt;
    &lt;meta charset="utf-8" /&gt;
    &lt;meta name="viewport" content="width=device-width, initial-scale=1" /&gt;
    &lt;link rel="stylesheet" href="~/dist/site.css" asp-append-version="true" /&gt;
&lt;/head&gt;
&lt;body&gt;
    &lt;div class="container mx-auto px-4 py-8"&gt;
        &lt;h1 class="text-4xl font-bold mb-8"&gt;@Model.Value("title")&lt;/h1&gt;
        &lt;div class="prose max-w-none mb-12"&gt;
            @await Html.GetBlockGridHtmlAsync(Model, "body")
        &lt;/div&gt;
        &lt;div class="grid grid-cols-1 md:grid-cols-2 gap-8"&gt;
            @foreach(var post in Model.Children&lt;ContentModels.BlogPost&gt;())
            {
                &lt;article class="border rounded-lg p-6 shadow"&gt;
                    &lt;h2 class="text-2xl font-bold mb-2"&gt;&lt;a href="@post.Url()"&gt;@post.Value("title")&lt;/a&gt;&lt;/h2&gt;
                    &lt;p class="text-gray-600 text-sm mb-4"&gt;@post.Value("date")&lt;/p&gt;
                    &lt;p class="text-gray-700"&gt;@post.Value("excerpt")&lt;/p&gt;
                &lt;/article&gt;
            }
        &lt;/div&gt;
    &lt;/div&gt;
    &lt;script type="module" src="~/dist/main.js" asp-append-version="true"&gt;&lt;/script&gt;
&lt;/body&gt;
&lt;/html&gt;

