@model ImageModel
@using Umbraco.Bench.Umbraco.Models;

<figure class="my-8">
    @if (!string.IsNullOrEmpty(Model.ImageUrl))
    {
        <img src="@Model.ImageUrl" alt="@Model.ImageAlt" class="w-full rounded-lg" />
    }
    @if (Model.Caption != null)
    {
        <figcaption class="text-center text-gray-600 text-sm mt-2 prose">
            @Html.Raw(Model.Caption.Value<string>("markup"))
        </figcaption>
    }
</figure>

